# backend.sh - Deploy nereidforge-backend (API + Worker)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
LIB_DIR="$REPO_ROOT/infra/scripts/lib"
APP_CHARTS_DIR="$REPO_ROOT/charts"
HELM="helm"

source "$LIB_DIR/common.sh"
source "$LIB_DIR/config.sh"

# Read fixed LS/CVAT tokens (generated by 10_infra/bootstrap-tokens.sh)
TOKEN_FILE="$NF_HANDOFF_DIR/service-tokens.env"
if [[ -f "$TOKEN_FILE" ]]; then
    source "$TOKEN_FILE"
fi

TENANT="${1:-nereidforge}"

# Resolve every site-specific URL before any cluster operation. An explicit
# FRONTEND_HOST supports single-domain installs; BASE_DOMAIN still supplies the
# Label Studio and CVAT ingress URLs.
if [[ -z "${FRONTEND_HOST}" ]]; then
    validate_required BASE_DOMAIN || exit 1
    FRONTEND_HOST="$TENANT.$BASE_DOMAIN"
fi
validate_required BASE_DOMAIN FRONTEND_HOST DEX_STATIC_EMAIL \
    PG_ADMIN_PASSWORD JWT_SECRET \
    SEAWEEDFS_S3_ACCESS_KEY SEAWEEDFS_S3_SECRET_KEY \
    NEREIDFORGE_LABELSTUDIO_TOKEN NEREIDFORGE_CVAT_TOKEN || exit 1
export FRONTEND_HOST

SSO_MODE="${SSO_MODE:-oidc}"
SSO_OIDC_ISSUER="${SSO_OIDC_ISSUER:-}"
SSO_NS_BASE_URL="${SSO_NS_BASE_URL:-}"
case "$SSO_MODE" in
    oidc) validate_required SSO_OIDC_ISSUER || exit 1 ;;
    ns) validate_required SSO_NS_BASE_URL || exit 1 ;;
    local) ;;
    *) log_err "SSO_MODE must be local, ns, or oidc"; exit 1 ;;
esac

log_info "========== Deploy NereidForge Backend ($TENANT) =========="

# Namespace (istio-injection) + the optional registry pull secret + the
# pg-nereidforge-credentials secret are rendered by the chart
# (templates/namespace.yaml, registry-secret.yaml, pg-credentials.yaml). The
# registry secret renders only when registry.host, registry.username and
# registry.password are all supplied; default public installs render no secret.
# The pg secret is
# replicated from nereidforge via lookup.

# NF_BACKEND_IMAGE is the public flat GHCR ref from lib/config.sh.
NF_BACKEND_IMAGE="${NF_BACKEND_IMAGE:?config.sh failed to provide NF_BACKEND_IMAGE}"
NF_BACKEND_REPO="${NF_BACKEND_IMAGE%:*}"
NF_BACKEND_TAG="${NF_BACKEND_IMAGE##*:}"

log_info "Image repo: $NF_BACKEND_REPO"
log_info "Image tag: $NF_BACKEND_TAG"

cd "$APP_CHARTS_DIR/nereidforge-backend"

# The namespace is pre-created by 10_infra (kubectl). Pre-adopt it for this
# release so the chart's templates/namespace.yaml does not fail Helm's
# ownership validation; the chart keeps resource-policy: keep on uninstall.
kubectl label namespace "$TENANT" app.kubernetes.io/managed-by=Helm --overwrite >/dev/null
kubectl annotate namespace "$TENANT" \
    meta.helm.sh/release-name=nereidforge-backend \
    meta.helm.sh/release-namespace="$TENANT" --overwrite >/dev/null

# Adopt any pre-existing harbor-registry-secret (e.g. created by the operator
# for an authenticated registry mirror) so this Helm release can own it. The
# block is a no-op when the secret does not exist; default installs create none.
if kubectl get secret harbor-registry-secret -n "$TENANT" >/dev/null 2>&1; then
    kubectl label secret harbor-registry-secret -n "$TENANT" \
        app.kubernetes.io/managed-by=Helm --overwrite >/dev/null
    kubectl annotate secret harbor-registry-secret -n "$TENANT" \
        meta.helm.sh/release-name=nereidforge-backend \
        meta.helm.sh/release-namespace="$TENANT" --overwrite >/dev/null
fi

# Copy internal CA bundle from cert-manager ns into tenant ns for outbound TLS
# to the configured SSO issuer and other internal endpoints. cert-manager is a cluster
# prerequisite since 2026-10-19 (suite layer: NereidOverview/deploy/prereqs);
# NF does not install it, but the secret contract stands — its presence
# (nereid-internal-ca) controls whether the api pod mounts it.
# The source secret (cert-manager/nereid-internal-ca-tls) stores ca.crt as base64;
# we must decode it so the mounted file is a valid PEM certificate.
if kubectl get secret nereid-internal-ca-tls -n cert-manager >/dev/null 2>&1; then
    kubectl get secret nereid-internal-ca-tls -n cert-manager -o jsonpath='{.data.ca\.crt}' \
        | base64 -d \
        | kubectl create secret generic nereid-internal-ca -n "$TENANT" \
            --from-file=ca.crt=/dev/stdin --dry-run=client -o yaml | kubectl apply -f - >/dev/null
    log_ok "Internal CA bundle replicated to $TENANT/nereid-internal-ca"
else
    log_warn "cert-manager/nereid-internal-ca-tls not found; outbound TLS to SSO may fail"
fi

$HELM upgrade --install nereidforge-backend . -n "$TENANT" --create-namespace \
    --set image.repository="$NF_BACKEND_REPO" \
    --set image.tag="$NF_BACKEND_TAG" \
    --set config.database.host="nereidforge-postgresql-rw.nereidforge.svc.cluster.local" \
    --set config.database.port=5432 \
    --set config.database.name="$TENANT" \
    --set config.database.user="nereidforge" \
    --set config.database.password="" \
    --set postgresql.existingSecret="pg-nereidforge-credentials" \
    --set postgresql.existingSecretKey="password" \
    --set secrets.database.password="$PG_ADMIN_PASSWORD" \
    --set secrets.auth.jwt_secret="$JWT_SECRET" \
    --set secrets.storage.s3_access_key="$SEAWEEDFS_S3_ACCESS_KEY" \
    --set secrets.storage.s3_secret_key="$SEAWEEDFS_S3_SECRET_KEY" \
    --set secrets.kfp.object_store_access_key="$SEAWEEDFS_S3_ACCESS_KEY" \
    --set secrets.kfp.object_store_secret_key="$SEAWEEDFS_S3_SECRET_KEY" \
    --set config.sso.mode="$SSO_MODE" \
    --set config.sso.oidc.issuer="$SSO_OIDC_ISSUER" \
    --set config.sso.oidc.client_id="${SSO_OIDC_CLIENT_ID:-nereidforge}" \
    --set config.sso.oidc.redirect_url="${SSO_OIDC_REDIRECT_URL:-https://${FRONTEND_HOST}/auth/callback}" \
    --set config.sso.oidc.frontend_base_url="${SSO_OIDC_FRONTEND_BASE_URL:-https://${FRONTEND_HOST}}" \
    --set config.sso.ns.base_url="$SSO_NS_BASE_URL" \
    --set config.sso.ns.product_id="${SSO_NS_PRODUCT_ID:-forge}" \
    --set config.labelstudio.public_host="https://labelstudio.$BASE_DOMAIN" \
    --set config.cvat.public_host="https://cvat.$BASE_DOMAIN" \
    --set secrets.sso.oidc.client_secret="${SSO_OIDC_CLIENT_SECRET:-}" \
    --set secrets.sso.ns.client_secret="${SSO_NS_CLIENT_SECRET:-}" \
    --set secrets.labelstudio.token="$NEREIDFORGE_LABELSTUDIO_TOKEN" \
    --set secrets.cvat.token="$NEREIDFORGE_CVAT_TOKEN" \
    --wait --timeout 10m

# Seed the platform super-admin ('admin' in the 'default' tenant) so the
# browser login (and 60_verify's nf-check) works on a brand-new database.
# The app has no startup auto-seed; without this a fresh CNPG datadir has an
# empty users table and every login fails with "invalid credentials".
# Idempotent: skips when the user already exists.
# Password policy (2026-10-29): NF_ADMIN_PASSWORD if explicitly provided,
# otherwise a random 48-hex secret generated on first seed. No built-in
# default administrator credential is created. Explicitly supplying the
# password also rotates an existing legacy admin through AdminService; leaving
# it unset never changes an existing password. The hand-off is written below
# NF_HANDOFF_DIR as admin-credentials.env (outside Git, mode 0600).
NF_ADMIN_PASSWORD_EXPLICIT=false
if [[ -n "${NF_ADMIN_PASSWORD:-}" ]]; then
    NF_ADMIN_PASSWORD_EXPLICIT=true
fi
: "${NF_ADMIN_PASSWORD:=}"
CRED_FILE="$NF_HANDOFF_DIR/admin-credentials.env"
if kubectl rollout status deployment/nereidforge-api -n "$TENANT" --timeout=180s >/dev/null 2>&1; then
    SEED_PY=$(cat <<'PYEOF'
import os
from sqlalchemy import select
from app.db.session import SessionLocal
from app.models.orm import User
from app.services.admin import AdminService
db = SessionLocal()
svc = AdminService(db)
exists = db.scalar(select(User).where(User.username=="admin"))
if exists and os.environ.get("NF_ADMIN_ROTATE") != "true":
    print("admin exists, skip")
elif exists:
    svc.update_user(exists.id, {"password": os.environ["NF_ADMIN_PASSWORD"]})
    print("admin password rotated")
else:
    pw = os.environ["NF_ADMIN_PASSWORD"]
    u = svc.create_user("admin", os.environ.get("NF_ADMIN_EMAIL", ""), "Platform Admin", pw, "default", ["admin","user"])
    print("admin seeded", u["username"], u["tenant_id"])
db.close()
PYEOF
)
    if [[ -z "$NF_ADMIN_PASSWORD" ]] && ! kubectl exec -n "$TENANT" deployment/nereidforge-api -c api -- \
        python3 -c 'from sqlalchemy import select; from app.db.session import SessionLocal; from app.models.orm import User; db=SessionLocal(); print("yes" if db.scalar(select(User).where(User.username=="admin")) else "no"); db.close()' 2>/dev/null | grep -q yes; then
        NF_ADMIN_PASSWORD=$(openssl rand -hex 24)
        log_info "Generated a random platform administrator password (48 hex)"
    fi
    SEED_OUT=$(kubectl exec -n "$TENANT" deployment/nereidforge-api -c api -- \
        env NF_ADMIN_PASSWORD="$NF_ADMIN_PASSWORD" NF_ADMIN_ROTATE="$NF_ADMIN_PASSWORD_EXPLICIT" \
        NF_ADMIN_EMAIL="${NF_ADMIN_EMAIL:-}" \
        python3 -c "$SEED_PY" 2>&1 || true)
    if echo "$SEED_OUT" | grep -qE "admin seeded|admin password rotated"; then
        ensure_private_dir "$NF_HANDOFF_DIR"
        umask 077
        {
            echo "# NereidForge platform admin — generated by 40_nereidforge/backend.sh on first seed."
            echo "# Save this file securely; it is gitignored and never committed."
            echo "NF_ADMIN_USERNAME=admin"
            echo "NF_ADMIN_PASSWORD=$NF_ADMIN_PASSWORD"
        } > "$CRED_FILE"
        chmod 600 "$CRED_FILE"
        log_ok "Platform administrator credentials created or rotated (admin / strong password) -> $CRED_FILE"
    elif echo "$SEED_OUT" | grep -q "admin exists, skip"; then
        log_ok "Platform administrator already exists; skipping seed without changing the password"
        [[ -f "$CRED_FILE" ]] || log_warn "Credential file $CRED_FILE is missing; set NF_ADMIN_PASSWORD and follow the runbook to rotate it"
    else
        log_warn "Platform administrator seed failed; create it manually: $SEED_OUT"
    fi
else
    log_warn "API is not ready; skipping platform administrator seed"
fi

# Register first-time pipeline/experiment IDs and upload the current versions.
# Running in the API pod keeps KFP and PostgreSQL on their verified in-cluster
# paths; the uploader persists each new ID so interrupted installs can resume.
# PYTHONPATH=/app makes `import app.*` resolve inside the image (the script's
# own sys.path[0] is /app/kfp-pipelines); HOME is forced because the kfp SDK
# always reads its user-identity context from $HOME/.config/kfp/context.json —
# a custom KFP_CONTEXT_DIR is ignored by the SDK, which left every call
# unauthenticated (401 "there is no user identity header", pit 193).
log_info "Synchronize NereidForge KFP pipelines (initial registration and current-version upload)"
kubectl exec -n "$TENANT" deployment/nereidforge-api -c api -- \
    env PYTHONPATH=/app \
    HOME=/tmp \
    KFP_HOST="http://ml-pipeline.kubeflow:8888" \
    KFP_CONFIG_HOST="http://ml-pipeline.kubeflow:8888" \
    KFP_NAMESPACE="$TENANT" \
    KFP_USERID="$DEX_STATIC_EMAIL" \
    python3 /app/kfp-pipelines/upload_pipelines.py

log_ok "Backend deployment complete"
